// ResolveTaskTargetRepo returns the explicit target_repo label if present, or infers the right repository from task context.
func (s *Server) ResolveTaskTargetRepo(qt queue.QueuedTask) string {
	if explicit := extractSingleLabel(qt.Labels, "repo:", ""); explicit != "" {
		if st, err := os.Stat(explicit); err == nil && st.IsDir() {
			return explicit
		}
	}
	lower := strings.ToLower(qt.ExternalID + " " + qt.Title + " " + qt.Description)
	workRoot := filepath.Dir(s.Root)
	if strings.TrimSpace(s.Root) == "" || workRoot == "." || workRoot == "/" {
		workRoot = "/Users/trainguyen/Documents/work"
	}
	cdsPath := filepath.Join(workRoot, "data-hub", "centralized-data-service")
	if strings.Contains(lower, "mongo") || strings.Contains(lower, "destination") || strings.Contains(lower, "sink") || strings.Contains(lower, "recon") || strings.Contains(lower, "transmute") || strings.Contains(lower, "centralized-data-service") {
		if st, err := os.Stat(cdsPath); err == nil && st.IsDir() {
			return cdsPath
		}
	}
	cmsSvcPath := filepath.Join(workRoot, "data-hub", "cdc-cms-service")
	if strings.Contains(lower, "cms-service") {
		if st, err := os.Stat(cmsSvcPath); err == nil && st.IsDir() {
			return cmsSvcPath
		}
	}
	cmsWebPath := filepath.Join(workRoot, "data-hub", "cdc-cms-web")
	if strings.Contains(lower, "cms-web") {
		if st, err := os.Stat(cmsWebPath); err == nil && st.IsDir() {
			return cmsWebPath
		}
	}
	if strings.TrimSpace(s.Root) != "" {
		return s.Root
	}
	return "."
}

